import Image from "next/image";

interface RafiLogoProps {
  iconOnly?: boolean;
  /** Height of the fox mark in px; the wordmark scales with it. */
  size?: number;
  /** Always use the white wordmark (for permanently dark surfaces like the footer). */
  onDark?: boolean;
  className?: string;
}

// Intrinsic sizes of the assets generated by scripts/gen-logo.mjs
const MARK_RATIO = 298 / 307;
const WORDMARK_RATIO = 283 / 90;

export default function RafiLogo({
  iconOnly = false,
  size = 36,
  onDark = false,
  className = "",
}: RafiLogoProps) {
  const mark = (
    <Image
      src="/images/rafi9i-mark.png"
      alt={iconOnly ? "Rafi9i" : ""}
      width={Math.round(size * MARK_RATIO)}
      height={size}
      className={iconOnly ? `object-contain ${className}` : "object-contain"}
      priority
    />
  );

  if (iconOnly) return mark;

  const wordHeight = Math.round(size * 0.62);
  const wordWidth = Math.round(wordHeight * WORDMARK_RATIO);

  return (
    <span className={`inline-flex items-center gap-2 ${className}`} role="img" aria-label="Rafi9i">
      {mark}
      {onDark ? (
        <Image src="/images/rafi9i-wordmark-light.png" alt="" width={wordWidth} height={wordHeight} />
      ) : (
        <>
          <Image src="/images/rafi9i-wordmark.png" alt="" width={wordWidth} height={wordHeight} className="dark:hidden" />
          <Image
            src="/images/rafi9i-wordmark-light.png"
            alt=""
            width={wordWidth}
            height={wordHeight}
            className="hidden dark:block"
          />
        </>
      )}
    </span>
  );
}
